1: //! A ready-made command line for video binaries (feature `cli`). One call gives every video
2: //! the same tools for rendering and for checking the result without watching it:
3: //!
4: //! ```ignore
5: //! fn main() -> std::process::ExitCode {
6: //!     let media = MyMedia::prepare().unwrap();
7: //!     let video = MyVideo { media: &media };
8: //!     fframes::cli::new(&video, RenderOptions { media: Some(&media), ..Default::default() }).run()
9: //! }
10: //! ```
11: //!
12: //! Everything else is optional: `.backend(..)` renders with another backend (the Skia renderer;
13: //! previews then use it too), `.preview(fframes_native_player::cli_preview)` adds the real-time
14: //! window, `.default_output("out.webm")` changes the file `render` writes. Flags of your own go
15: //! into a `#[derive(clap::Args)]` struct: `let args = cli::parse::<MyArgs>();`, build the video
16: //! from `args.app`, then `cli::new(&video, options).args(args).run()`.
17: use super::{
18:     CpuFrameRenderer, FFramesRenderBackend, FFramesRendererError, FrameRenderer, FrameReport,
19:     Previewer, RgbaFrame,
20:     continuity::{PopDetector, PopKind},
21:     element_labels::{self, LabelledElement},
