export const StickFigure: React.FC<{
  x: number;
  y: number;
  scale?: number;
  pose?: 'stand' | 'run' | 'think' | 'shock';
  color?: string;
  beanie?: boolean;
}> = ({x, y, scale = 1, pose = 'stand', color = C.white, beanie = false}) => {
  const f = useCurrentFrame();
  const bob = Math.sin(f / 4) * 4;

  let leftArm = "M 0 35 L -35 55";
  let rightArm = "M 0 35 L 35 55";
  let leftLeg = "M 0 95 L -25 160";
  let rightLeg = "M 0 95 L 25 160";

  if (pose === 'run') {
    const cycle = Math.sin(f / 3);
    leftArm = `M 0 35 L ${-40 * cycle} 25`;
    rightArm = `M 0 35 L ${40 * cycle} 25`;
    leftLeg = `M 0 95 L ${-35 * cycle} 150`;
    rightLeg = `M 0 95 L ${35 * cycle} 150`;
  } else if (pose === 'think') {
    rightArm = "M 0 35 L 25 20 L 15 -10";
    leftArm = "M 0 35 L -30 70";
  } else if (pose === 'shock') {
    leftArm = "M 0 35 L -45 -10";
    rightArm = "M 0 35 L 45 -10";
    leftLeg = "M 0 95 L -35 155";
    rightLeg = "M 0 95 L 35 155";
  }

  return (
    <g transform={`translate(${x}, ${y + (pose === 'run' ? bob : 0)}) scale(${scale})`}>
      {/* Head */}
      <circle cx="0" cy="0" r="24" fill="none" stroke={color} strokeWidth="6" strokeLinecap="round" />
      {beanie && (
        <path d="M -22 -6 Q 0 -36 22 -6 Z" fill={C.red} stroke={C.red} strokeWidth="3" />
