      {/* Spine */}
      <line x1="0" y1="24" x2="0" y2="95" stroke={color} strokeWidth="6" strokeLinecap="round" />
      {/* Limbs */}
      <path d={leftArm} stroke={color} strokeWidth="6" strokeLinecap="round" fill="none" />
      <path d={rightArm} stroke={color} strokeWidth="6" strokeLinecap="round" fill="none" />
      <path d={leftLeg} stroke={color} strokeWidth="6" strokeLinecap="round" fill="none" />
      <path d={rightLeg} stroke={color} strokeWidth="6" strokeLinecap="round" fill="none" />
    </g>
  );
};

